class Solution {
public:
    int longestIdealString(string s, int k) {
        int best[26] = {0};
        int ans = 0;
        for (char c : s) {
            int idx = c - 'a';
            int m = 0;
            for (int j = 0; j < 26; j++) {
                int diff = j - idx;
                if (diff < 0) diff = -diff;
                if (diff <= k && best[j] > m) {
                    m = best[j];
                }
            }
            best[idx] = m + 1;
            if (best[idx] > ans) ans = best[idx];
        }
        return ans;
    }
};
